using Eto.Forms;using Rhino;using Rhino.DocObjects;
namespace RhinoContextAssist;
internal sealed class ContextAssistController:IDisposable{readonly UITimer timer;readonly ContextAssistSettings settings;ContextAssistPopup? popup;DateTime due=DateTime.MaxValue;public ContextAssistController(ContextAssistSettings s){settings=s;timer=new UITimer{Interval=.1};timer.Elapsed+=(_,_)=>Tick();}public void Start(){RhinoDoc.SelectObjects+=Changed;RhinoDoc.DeselectObjects+=Changed;RhinoDoc.DeselectAllObjects+=Cleared;timer.Start();}void Changed(object?s,RhinoObjectSelectionEventArgs e){Close();due=DateTime.UtcNow.AddMilliseconds(settings.SelectionDelayMs);}void Cleared(object?s,RhinoDeselectAllObjectsEventArgs e)=>Hide();void Tick(){var d=RhinoDoc.ActiveDoc;if(!settings.Enabled||d==null||d.IsCommandRunning)return;if(due==DateTime.MaxValue||DateTime.UtcNow<due)return;due=DateTime.MaxValue;var c=SelectionAnalyzer.Analyze(d);var a=ActionService.Get(c,settings);if(a.Count==0)return;popup=new(Execute,Hide,settings);popup.UpdateActions(c,a);popup.ShowAt(c,settings.PositionMode);}void Execute(ContextAction a){ContextAssistPlugIn.Instance!.LastAction=a;settings.RecordUsage(a.Id);Hide();RhinoApp.RunScript(a.Macro,false);}public void Hide(){due=DateTime.MaxValue;Close();}void Close(){try{popup?.Close();}catch{}popup=null;}public void Dispose(){timer.Stop();RhinoDoc.SelectObjects-=Changed;RhinoDoc.DeselectObjects-=Changed;RhinoDoc.DeselectAllObjects-=Cleared;Close();}}
